$cats['Hidden Within']['Hidden Within Faces Within Faces'] = @('Faces in Nature','Two Souls, One Face','The Face Behind the Face','The Lovers'' Compass','The Many Faces of One','The Face in the Flame','The Portrait in the Eye','The Whispering Faces','The Sleeping World','The Face That Changes')
$cats['Hidden Within']['Hidden Within Animals Within Animals'] = @('Wolf Within','The Lion''s Secret','The Raven''s Secret','The Serpent''s Guardian','The Owl''s Wisdom','The Butterfly''s Secret','The Whale''s World','The Fox and the Forest','The Two Ravens','The Guardian Within')
$cats['Hidden Within']['Hidden Within Love and Connection'] = @('Two Become One','The Kiss in the Negative Space','The Face of a Memory','Mother and Child','The Family Tree','The Unspoken Bond','The Heart Remembers','The Embrace','The Faces in the Moon','Forever Connected')
$cats['Hidden Within']['Hidden Within Skulls and the Cycle of Life'] = @('Life in Death','The Lovers'' Skull','The Garden Beneath','The Face in the Bone','The Phoenix Within','The Clockwork Skull','The Face of Decay','The Bone Cathedral','The Watcher in the Skull','The Endless Cycle')
$cats['Hidden Within']['Hidden Within Nature Hiding Other Worlds'] = @('Faces in the Forest','The Tree of Faces','The River''s Secret','The Mountain Guardian','The Flower Within','The Ocean''s Face','The Leaves Remember','The Two Trees','The Storm Within','The Garden of Dreams')
$cats['Hidden Within']['Hidden Within Water Sky and Cosmos'] = @('The Universe in an Eye','The Moon''s Hidden Face','The Galaxy Within','The Nebula''s Guardian','The Ocean in the Sky','The Star Map','The Eclipse Within','The Sleeping Universe','The Cloud Cathedral','The Cosmic Lovers')
$cats['Hidden Within']['Hidden Within Objects with Secret Identities'] = @('The Mirror''s Secret','The Pocket Watch Within','The Book of Worlds','The Mask Behind the Mask','The Keyhole to Another World','The Bottle''s Secret','The Crystal Guardian','The Violin''s Soul','The Broken Statue','The Mask of Nature')
$cats['Hidden Within']['Hidden Within Impossible Architecture and Illusions'] = @('The Face in the City','The Impossible Staircase','The Cathedral of Faces','The Bridge Between Worlds','The Window to Elsewhere','The City That Watches','The Endless Corridor','The Face in the Ruins','The Two Dimensions','The Portal Within')
$cats['Hidden Within']['Hidden Within Transformations'] = @('The Face Becoming a Wolf','The Butterfly Becoming a Woman','The Tree Becoming a Face','The Ocean Becoming a Woman','The Mechanical Face','The Phoenix Within the Flame','The Face in the Smoke','The Living Sculpture','The Fractured Reality','The Shape of Dreams')
$cats['Hidden Within']['Hidden Within Unexpected Discoveries'] = @('The Impossible Hand','The Face Between Worlds','The Hidden Creature','The Sound Made Visible','The Emotion Within','The World in a Tear','The Face of Time','The Infinite Creature','The Tattoo That Reveals Another Tattoo','The Ultimate Hidden World')
$mine = @(); foreach ($c in $cats.Keys) { $mine += @($cats[$c].Keys) }
$taken = @{}; $tt.specific.PSObject.Properties | ? { $mine -notcontains $_.Name } | % { $_.Value | ? { $_ } | % { $taken[(& $slug $_)] = 1 } }
$final = @{}
foreach ($c in $cats.Keys) {
  $kinds = @($cats[$c].Keys)
  $had = @($tt.subjects.$c | ? { $_ }); "  " + $c + " already has " + $had.Count + " sets - the new ones are ADDED, nothing removed"
  $newKinds = @($kinds | ? { $had -notcontains $_ })
  if ($newKinds.Count -lt $kinds.Count) { "  " + ($kinds.Count - $newKinds.Count) + " of these sets are already in the catalogue from the first run - kept, not added twice" }
  if ($tt.subjects.PSObject.Properties[$c]) { $tt.subjects.$c = @($had + $newKinds) } else { $tt.subjects | Add-Member -NotePropertyName $c -NotePropertyValue $kinds }
  foreach ($k in $kinds) {
    $names = @($cats[$c][$k] | % { $o = $_; if ($taken.ContainsKey((& $slug $o))) { $nn = $o + " in " + $c + " Style"; "  RENAMED: " + $nn | Out-Host } else { $nn = $o }; $final[$o] = $nn; $nn })
    if ($tt.specific.PSObject.Properties[$k]) { $tt.specific.$k = $names } else { $tt.specific | Add-Member -NotePropertyName $k -NotePropertyValue $names }
  }
}
$json = $tt | ConvertTo-Json -Depth 20 -Compress
$check = $json | ConvertFrom-Json
$afterCats = @($check.subjects.PSObject.Properties).Count
if ($clash -or $afterCats -lt $beforeCats -or $json.Length -lt ($got.raw.Length * 0.9)) { "  SAFETY STOP - the new catalog looks smaller than the old one, nothing written" } else {
$tmp = Join-Path $env:TEMP "card-tree-new.json"
[System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding $false))
npx wrangler kv key put --namespace-id $ns "card:tree" --path $tmp --remote 2>$null | Out-Null
"  catalog written in ONE save: " + $beforeCats + " categories before, " + $afterCats + " after"
"  saving the split-card settings and the tattoo descriptions..."
$n = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) {
  $ks = & $slug $k
  RUN ("SETKV render:" + $ks + " The tattoo in both panels is identical.") | Out-Null
  RUN ("SETKV shape:" + $ks + " 3:2") | Out-Null
  RUN ("SETKV split:" + $ks + " yes") | Out-Null
  foreach ($o in $cats[$c][$k]) { RUN ("SETKV build:" + (& $slug $final[$o]) + " " + $b[$o]) | Out-Null; $n++ }
} }
"  " + $n + " descriptions saved - waiting 70 seconds so every server sees the new catalog..."
Start-Sleep -Seconds 70
$got2 = Read-Tree
$short = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) { $h = @($got2.tree.specific.$k | ? { $_ }).Count; if ($h -ne $cats[$c][$k].Count) { "  STILL SHORT: " + $k + " has " + $h; $short++ } } }
if ($short) { "== " + $short + " sets short - send me this output ==" } else {
if (-not $short) {
"== saved: Universe Within, Impossible Fusion, Hidden Within - 300 designs =="
$old = ((RUN "GETKV config:source:redo:model" | Out-String) | ConvertFrom-Json).payload.reply
if (-not $old) { $old = "" }
$bf = Join-Path (Get-Location) "redo-model-before.txt"
# A SECOND RUN KEEPS THE FIRST RUN'S RECORD: by then the setting already says gpt-image-2, which is not what it was before.
if (Test-Path $bf) { $old = (Get-Content $bf -Raw).Trim(); "  (kept the model saved by the first run)" } else { [System.IO.File]::WriteAllText($bf, [string]$old) }
"  the REDO model was: " + $old + " - saved to redo-model-before.txt; drawing this set on gpt-image-2"
RUN "SETKV config:source:redo:model gpt-image-2" | Out-Null
"  waiting 70 seconds so every server sees the model setting..."
Start-Sleep -Seconds 70
"== THE THREE TEST CARDS, THROUGH THE REAL BATCH ROAD (REDO) =="
foreach ($c in $cats.Keys) { "-- test card for " + $c + ": " + $final[$test[$c]]; RUN ("REDO " + $final[$test[$c]]) }
}
}
}
}
